import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N = int(input())
    C = [input().strip() for _ in range(N)]

    INF = 10**9
    dist = [[INF] * N for _ in range(N)]
    q = deque()

    for i in range(N):
        dist[i][i] = 0
        q.append((i, i))

    in_by = [[[] for _ in range(26)] for _ in range(N)]
    out_by = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        row = C[i]
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - ord('a')
                out_by[i][c].append(j)
                in_by[j][c].append(i)
                if i != j and dist[i][j] > 1:
                    dist[i][j] = 1
                    q.append((i, j))

    while q:
        a, b = q.popleft()
        d = dist[a][b]
        nd = d + 2

        in_a = in_by[a]
        out_b = out_by[b]

        for c in range(26):
            preds = in_a[c]
            if not preds:
                continue
            succs = out_b[c]
            if not succs:
                continue

            for p in preds:
                row = dist[p]
                for s in succs:
                    if nd < row[s]:
                        row[s] = nd
                        q.append((p, s))

    ans = []
    for i in range(N):
        ans.append(' '.join(str(dist[i][j] if dist[i][j] < INF else -1) for j in range(N)))

    print('\n'.join(ans))

