import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = [0] + list(map(int, data[1:1 + N]))

    bit = [0] * (N + 1)
    for i in range(1, N + 1):
        bit[i] = i & -i

    def update(idx, delta):
        while idx <= N:
            bit[idx] += delta
            idx += idx & -idx

    def find_kth(k):
        idx = 0
        bitmask = 1 << (N.bit_length() - 1)
        while bitmask:
            nxt = idx + bitmask
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            bitmask >>= 1
        return idx + 1

    ans = [0] * (N + 1)

    for i in range(N, 0, -1):
        pos = find_kth(P[i])
        ans[pos] = i
        update(pos, -1)

    print(' '.join(map(str, ans[1:])))

